<style lang="scss">
.header-logo {
	display: flex;
	align-items: center;
	text-decoration: none;
	gap: 18px;
	flex-shrink: 0;
	padding: 0 24px;

	&__product-name {
		display: block;
		font-size: 1.25rem;
		font-weight: 600;
		white-space: nowrap;
		color: light-dark(var(--ion-color-primary), var(--color-main-text));
	}

	&__ionos,
	&__product {
		display: block;
		color: light-dark(var(--ion-color-primary), var(--color-main-text));
	}

	&__strato {
		display: block;
		color: light-dark(#FF7800, var(--color-main-text));
	}

	&__fasthosts {
		display: block;
		color: light-dark(#031A4A, var(--color-main-text));
	}

	&__homepl {
		display: block;
		--homepl-primary: light-dark(#1B1B1B, var(--color-main-text));
		--homepl-accent: light-dark(#E20000, var(--color-main-text));
	}
}
</style>
